begin
  if (select count(*) from public.safety_spots where facility_type='aed' and active and not duplicate_candidate) <> 39699
     then raise exception 'Public baseline changed; reconcile again'; end if;
  if (select count(*) from dev10_batch) <> 46
     or (select count(distinct source_key) from dev10_batch) <> 46
     or (select count(*) from dev10_batch where not duplicate_candidate) <> 46
     then raise exception 'Batch cardinality changed'; end if;
  if exists (select 1 from dev10_batch where active is distinct from false
      or facility_type is distinct from 'aed' or name is null or name='' or address is null or address=''
      or latitude is null or longitude is null
      or latitude not between 35.53 and 35.69 or longitude not between 138.6 and 138.73
      or source_license is distinct from 'CC BY 4.0'
      or prefecture is distinct from '山梨県'
      or municipality is distinct from '笛吹市'
